const localizedAttributes=[];
document.querySelectorAll('[aria-label], [alt], [data-caption]').forEach(el=>{['aria-label','alt','data-caption'].forEach(attr=>{if(el.hasAttribute(attr))localizedAttributes.push({el,attr,en:el.getAttribute(attr)})})});
const enquiryLinks=[...document.querySelectorAll('a[href*="wa.me"]')].map(el=>({el,en:el.href}));
function setLanguage(value){
 language=value==='en'?'en':'bm';document.documentElement.lang=language==='en'?'en-MY':'ms-MY';
 document.querySelectorAll('[data-en][data-bm]').forEach(el=>el.textContent=el.dataset[language]);
 localizedAttributes.forEach(({el,attr,en})=>el.setAttribute(attr,translate(en)));
 document.querySelectorAll('[data-language]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.language===language)));
 enquiryLinks.forEach(({el,en})=>{const url=new URL(en);if(language==='bm'){const old=url.searchParams.get('text')||'';url.searchParams.set('text',old.includes('viewing')?'Hai, saya ingin mengatur lawatan unit pameran Ophira Resort Residences.':old.includes('facilit')?'Hai, sila kongsikan pelan kemudahan lengkap Ophira Resort Residences.':'Hai, saya ingin mendapatkan pelan lantai terkini dan maklumat unit yang tersedia di Ophira Resort Residences.')}el.href=url.href});
 document.title='Ophira Resort Residences, Dutamas | '+(language==='bm'?'Kediaman Pegangan Bebas':'Freehold Homes');
 const url=new URL(location.href);url.searchParams.set('lang',language);history.replaceState(null,'',url);
 try{localStorage.setItem('ophira-language',language)}catch{}
 document.dispatchEvent(new Event('languagechange'));
}
document.querySelectorAll('[data-language]').forEach(el=>el.addEventListener('click',()=>setLanguage(el.dataset.language)));
let preference;try{preference=localStorage.getItem('ophira-language')}catch{}
setLanguage(new URL(location.href).searchParams.get('lang')||preference||'bm');
